PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?subject ?label WHERE {
  ?subject rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "monument voor amsterdam"))
}
LIMIT 10

