SELECT ?subject ?maker ?makerLabel WHERE {
  ?subject ?titlePred ?title .
  FILTER(CONTAINS(LCASE(STR(?title)), "markt op het waterlooplein"))
  OPTIONAL { ?subject ?makerPred ?maker .
             FILTER(CONTAINS(LCASE(STR(?makerPred)), "maker"))
             OPTIONAL { ?maker rdfs:label ?makerLabel } }
}
LIMIT 10

